'use strict';

// Embed generated by Google Maps > Share > Embed a map for Parque Fundidora.
// This geographic map is deliberately independent of the uncalibrated 3D model.
window.VenueParkMap = (() => {
  const embedURL = 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3595.7778783180374!2d-100.2842344!3d25.6786569!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x86629561ff265483%3A0x1b7bd40783c3a9a8!2sParque%20Fundidora!5e0!3m2!1ses-419!2sus!4v1792310141025!5m2!1ses-419!2sus';
  const places = [
    ['park', 'Parque Fundidora', 'Parque Fundidora, Monterrey, Nuevo León, México'],
    ['lewis', 'Nave Lewis', 'Nave Lewis, Parque Fundidora, Monterrey, México'],
    ['horno3', 'Museo del Acero Horno 3', 'Museo del Acero horno 3, Parque Fundidora, Monterrey, México'],
    ['cintermex', 'Cintermex', 'CINTERMEX, Monterrey, Nuevo León, México']
  ];
  const byId = id => document.getElementById(id);
  let initialized = false, loadTimer = null;
  function links() {
    const place = places.find(p => p[0] === byId('park-destination').value) || places[0];
    const query = new URL('https://www.google.com/maps/search/');
    query.search = new URLSearchParams({api:'1',query:place[2]}).toString();
    byId('park-open').href = query.href;
    const directions = new URL('https://www.google.com/maps/dir/');
    // Omit origin: Google Maps obtains it with its own permission flow. Never send GPS from this app.
    directions.search = new URLSearchParams({api:'1',destination:place[2],travelmode:'walking',dir_action:'navigate'}).toString();
    byId('park-directions').href = directions.href;
    byId('park-directions').setAttribute('aria-label', 'Cómo llegar a '+place[1]+' a pie en Google Maps (abre otra pestaña)');
    byId('park-open').setAttribute('aria-label', 'Ver '+place[1]+' en Google Maps (abre otra pestaña)');
  }
  function loadMap(retry = false) {
    const frame = byId('park-frame'), status = byId('park-load-status');
    if(frame.getAttribute('src') && !retry) return;
    clearTimeout(loadTimer);
    if(!navigator.onLine) {status.hidden=false;status.textContent='Sin conexión. Puedes volver al Festival 3D o reintentar al recuperar internet.';return;}
    status.hidden=false;status.textContent='Cargando el mapa de Google…';
    frame.onload=()=>{clearTimeout(loadTimer);status.hidden=true;};
    frame.onerror=()=>{clearTimeout(loadTimer);status.hidden=false;status.textContent='No se pudo cargar el mapa. Reintenta o abre Google Maps desde el enlace inferior.';};
    frame.src=embedURL;
    loadTimer=setTimeout(()=>{status.hidden=false;status.textContent='El mapa tarda en cargar. Puedes reintentar o abrir Google Maps desde el enlace inferior.';},12000);
  }
  function setSource(real) {
    const app=byId('app');
    if(app.classList.contains('real-map-view')===real)return;
    window.VenueNavigation?.suspend();
    setBrowsing(false);
    app.classList.toggle('real-map-view',real);
    byId('park-map').hidden=!real;byId('park-tools').hidden=!real;
    byId('source-festival').setAttribute('aria-pressed',String(!real));
    byId('source-google').setAttribute('aria-pressed',String(real));
    if(real)loadMap();else {resize();schedule();}
    (real?byId('source-google'):byId('source-festival')).focus({preventScroll:true});
    announce(real?'Parque Fundidora en Google Maps. Los escenarios temporales están en la vista Festival 3D.':'Festival 3D. Recinto conceptual con los dos días y sus zonas.');
  }
  function initialize() {
    if(initialized)return;initialized=true;
    const app=byId('app');
    const toggle=document.createElement('div');toggle.className='map-source-switch';toggle.setAttribute('role','group');toggle.setAttribute('aria-label','Vista del mapa');
    toggle.innerHTML='<button type="button" id="source-festival" aria-pressed="true">Festival 3D</button><button type="button" id="source-google" aria-pressed="false">Google Maps</button>';
    const map=document.createElement('section');map.id='park-map';map.hidden=true;map.setAttribute('aria-label','Mapa real del Parque Fundidora en Google Maps');
    map.innerHTML='<p id="park-load-status" role="status">Cargando el mapa de Google…</p><iframe id="park-frame" title="Google Maps: Parque Fundidora, Monterrey" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>';
    const tools=document.createElement('section');tools.id='park-tools';tools.hidden=true;tools.setAttribute('aria-label','Indicaciones en el parque');
    tools.innerHTML='<div class="park-destination-field"><label for="park-destination">Destino en el parque</label><select id="park-destination"></select></div><div class="park-links"><a id="park-directions" target="_blank" rel="noopener noreferrer" class="park-primary">Cómo llegar '+svgIcon('chevron')+'</a><a id="park-open" target="_blank" rel="noopener noreferrer">Abrir Maps</a><button type="button" id="park-reload" class="icon-btn" aria-label="Recargar el mapa de Google" title="Recargar mapa">'+svgIcon('reset')+'</button></div><p class="park-context">Indicaciones a pie en Google Maps. Los accesos del festival pueden cambiar. Escenarios y servicios temporales: <button type="button" id="park-return">Festival 3D</button>.</p>';
    app.append(toggle,map,tools);
    for(const [value,name] of places){const option=document.createElement('option');option.value=value;option.textContent=name;byId('park-destination').append(option);}
    byId('park-destination').onchange=links;links();
    byId('source-festival').onclick=()=>setSource(false);byId('source-google').onclick=()=>setSource(true);byId('park-return').onclick=()=>setSource(false);byId('park-reload').onclick=()=>loadMap(true);
  }
  return {initialize,setSource};
})();
